import Flutter
import UIKit

/// Entry point of the iOS plugin.
///
/// Threading: Flutter delivers every host call on the main thread. Sync calls
/// (`platformInfo`, `ack`, `cancel`, …) only read cheap state or hand work to
/// an engine `Task`; async calls are generated by Pigeon as
/// `Task { @MainActor in try await api.x() }` and immediately await an
/// engine actor, so model loads, prefill and decoding never run on the main
/// thread. Results reach Dart on the main thread (Pigeon replies, event sink).
///
/// UNVERIFIED against the real iOS SDK, Flutter.framework, mlx-swift-lm and
/// FoundationModels: written from their documentation and sources and
/// type-checked only on Linux against hand-written stand-in modules
/// (tool/typecheck_swift.sh). The first real compile is CI on macOS.
public final class SherpaAppleMlPlugin: NSObject, FlutterPlugin, AppleMlHostApi {
  private let hub: EventHub
  private let gate: GpuGate
  private let mlx: MlxEngineAPI?
  private let fm: FmEngineAPI?
  private var lifecycle: LifecycleMonitor?

  /// Created by `register(with:)` on the main thread.
  override init() {
    let hub = EventHub()
    let gate = MainActor.assumeIsolated { GpuGate(open: UIApplication.shared.applicationState == .active) }
    self.hub = hub
    self.gate = gate
    self.mlx = Self.makeMlx(gate: gate, hub: hub)
    self.fm = Self.makeFm(hub: hub)
    super.init()
  }

  private static func makeMlx(gate: GpuGate, hub: EventHub) -> MlxEngineAPI? {
    #if canImport(MLXLLM)
      return MlxEngine(gate: gate, hub: hub)
    #else
      return nil
    #endif
  }

  private static func makeFm(hub: EventHub) -> FmEngineAPI? {
    #if canImport(FoundationModels)
      if #available(iOS 26.0, *) { return FoundationModelsEngine(hub: hub) }
    #endif
    return nil
  }

  private static var fmCompiled: Bool {
    #if canImport(FoundationModels)
      return true
    #else
      return false
    #endif
  }

  public static func register(with registrar: FlutterPluginRegistrar) {
    let instance = SherpaAppleMlPlugin()
    // setUp's handlers retain `instance` for the engine's lifetime.
    AppleMlHostApiSetup.setUp(binaryMessenger: registrar.messenger(), api: instance)
    EventsStreamHandler.register(with: registrar.messenger(), streamHandler: instance.hub)
    MainActor.assumeIsolated { instance.startLifecycle() }
  }

  @MainActor
  private func startLifecycle() {
    let mlx = self.mlx
    let monitor = LifecycleMonitor(
      gate: gate, hub: hub,
      onResign: { reason in await mlx?.pauseAll(reason: reason) },
      onMemoryWarning: { await mlx?.handleMemoryWarning() })
    monitor.start()
    lifecycle = monitor
  }

  // MARK: AppleMlHostApi

  func platformInfo() throws -> AmPlatformInfo {
    let mlx = self.mlx
    return MainActor.assumeIsolated {
      DeviceFacts.platformInfo(
        mlxCompiled: mlx != nil, fmCompiled: Self.fmCompiled,
        recommendedWorkingSet: mlx?.recommendedWorkingSetBytes)
    }
  }

  func fmAvailability() async throws -> AmFmAvailability {
    guard let fm = fm else {
      return AmFmAvailability(
        available: false, reason: Self.fmCompiled ? .osTooOld : .frameworkMissing, localeSupported: false)
    }
    return await fm.availability()
  }

  private func requireMlx() throws -> MlxEngineAPI {
    guard let mlx = mlx else {
      throw PluginError.make(.unsupported, "This build does not include MLX (CocoaPods build, or not iOS 17+).")
    }
    return mlx
  }

  private func requireFm() throws -> FmEngineAPI {
    guard let fm = fm else {
      throw PluginError.make(.unsupported, "Foundation Models needs iOS 26 and an SDK that includes it.")
    }
    return fm
  }

  func mlxLoad(request: AmMlxLoadRequest) async throws -> AmMlxModelInfo {
    try await requireMlx().load(request)
  }

  func mlxUnload(modelId: String) async throws {
    await mlx?.unload(modelId: modelId)
  }

  func mlxGenerate(request: AmMlxGenerateRequest) async throws {
    try await requireMlx().generate(request)
  }

  func mlxCountTokens(modelId: String, text: String) async throws -> Int64 {
    Int64(try await requireMlx().countTokens(modelId: modelId, text: text))
  }

  func mlxSavePromptCache(sessionKey: String, path: String) async throws -> Bool {
    try await requireMlx().savePromptCache(sessionKey: sessionKey, path: path)
  }

  func fmGenerate(request: AmFmGenerateRequest) async throws {
    try await requireFm().generate(request)
  }

  func fmSubmitToolResults(generationId: String, results: [AmToolResult]) throws {
    let fm = self.fm
    Task { await fm?.submitToolResults(generationId: generationId, results: results) }
  }

  func fmPrewarm(instructions: String?) throws {
    // "prewarm may not load assets if your app is running in the background".
    let background = MainActor.assumeIsolated { UIApplication.shared.applicationState == .background }
    guard !background, let fm = fm else { return }
    Task { await fm.prewarm(instructions: instructions) }
  }

  func cancel(generationId: String) throws {
    let mlx = self.mlx
    let fm = self.fm
    Task {
      await mlx?.cancel(generationId: generationId)
      await fm?.cancel(generationId: generationId)
    }
  }

  func ack(generationId: String, seq: Int64) throws {
    hub.ack(generationId: generationId, seq: seq)
  }

  func interruptAll(reason: String) throws {
    let mlx = self.mlx
    Task { await mlx?.pauseAll(reason: reason) }
  }

  func dropSession(engine: AmEngine, sessionKey: String) async throws {
    switch engine {
    case .mlx: await mlx?.dropSession(sessionKey)
    case .foundationModels: await fm?.dropSession(sessionKey)
    }
  }
}
